import { useState } from 'react';
import { Head, useForm, router } from '@inertiajs/react';
import AppLayout from '@/layouts/app-layout';
import type { BreadcrumbItem } from '@/types';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { 
    Eye, EyeOff, Key, Trash2, CheckCircle2, ShieldAlert, Wallet, 
    Layers, Plus, Pencil, Save, Code, Settings, Trash 
} from 'lucide-react';

const breadcrumbs: BreadcrumbItem[] = [
    {
        title: 'Super Admin Dashboard',
        href: '/super-admin/dashboard',
    },
    {
        title: 'Settings',
        href: '/super-admin/settings',
    },
];

interface SettingsData {
    razorpay_key_id: string;
    has_razorpay_key_secret: boolean;
    reseller_bank_name: string;
    reseller_account_holder: string;
    reseller_account_number: string;
    reseller_ifsc_code: string;
    reseller_upi_id: string;
    reseller_default_bonus_percentage: string;
}

interface Category {
    id: number;
    name: string;
    slug: string;
    created_at?: string;
}

interface CustomBlockField {
    name: string;
    label: string;
    type: 'text' | 'textarea' | 'number' | 'color';
    default: string;
}

interface CustomBlock {
    id: number;
    name: string;
    type: string;
    description: string | null;
    fields: CustomBlockField[];
    template_html: string;
    created_at?: string;
}

interface PageProps {
    settings: SettingsData;
    categories: Category[];
    customBlocks: CustomBlock[];
}

export default function SettingsIndex({ settings, categories = [], customBlocks = [] }: PageProps) {
    const [activeTab, setActiveTab] = useState<'config' | 'categories' | 'blocks'>('config');
    const [showSecret, setShowSecret] = useState(false);

    // 1. General Config Form
    const { data: configData, setData: setConfigData, post: postConfig, delete: destroyConfig, processing: configProcessing, reset: resetConfig, wasSuccessful: configSuccess } = useForm({
        razorpay_key_id: settings.razorpay_key_id || '',
        razorpay_key_secret: '',
        reseller_bank_name: settings.reseller_bank_name || '',
        reseller_account_holder: settings.reseller_account_holder || '',
        reseller_account_number: settings.reseller_account_number || '',
        reseller_ifsc_code: settings.reseller_ifsc_code || '',
        reseller_upi_id: settings.reseller_upi_id || '',
        reseller_default_bonus_percentage: settings.reseller_default_bonus_percentage || '0',
    });

    // 2. Category Form & Modal State
    const [isCategoryOpen, setIsCategoryOpen] = useState(false);
    const [editingCategory, setEditingCategory] = useState<Category | null>(null);
    const { data: categoryData, setData: setCategoryData, post: postCategory, put: putCategory, processing: categoryProcessing, errors: categoryErrors, reset: resetCategory } = useForm({
        name: '',
        slug: '',
    });

    // 3. Custom Block Form & Modal State
    const [isBlockOpen, setIsBlockOpen] = useState(false);
    const [editingBlock, setEditingBlock] = useState<CustomBlock | null>(null);
    const { data: blockData, setData: setBlockData, post: postBlock, put: putBlock, processing: blockProcessing, errors: blockErrors, reset: resetBlock } = useForm({
        name: '',
        type: '',
        description: '',
        fields: [] as CustomBlockField[],
        template_html: '',
    });

    const handleSaveConfig = (e: React.FormEvent) => {
        e.preventDefault();
        postConfig('/super-admin/settings', {
            onSuccess: () => {
                resetConfig('razorpay_key_secret');
            }
        });
    };

    const handleDeleteKey = (keyName: 'razorpay_key_id' | 'razorpay_key_secret') => {
        if (confirm(`Are you sure you want to delete this key setting: ${keyName.replace(/_/g, ' ')}?`)) {
            destroyConfig(`/super-admin/settings/${keyName}`, {
                onSuccess: () => {
                    if (keyName === 'razorpay_key_id') {
                        setConfigData('razorpay_key_id', '');
                    }
                }
            });
        }
    };

    // Category CRUD
    const handleAddCategory = () => {
        setEditingCategory(null);
        resetCategory();
        setCategoryData({ name: '', slug: '' });
        setIsCategoryOpen(true);
    };

    const handleEditCategory = (cat: Category) => {
        setEditingCategory(cat);
        setCategoryData({
            name: cat.name,
            slug: cat.slug,
        });
        setIsCategoryOpen(true);
    };

    const handleCategorySubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (editingCategory) {
            putCategory(`/super-admin/categories/${editingCategory.id}`, {
                onSuccess: () => {
                    setIsCategoryOpen(false);
                    resetCategory();
                }
            });
        } else {
            postCategory('/super-admin/categories', {
                onSuccess: () => {
                    setIsCategoryOpen(false);
                    resetCategory();
                }
            });
        }
    };

    // Custom Block CRUD
    const handleAddBlock = () => {
        setEditingBlock(null);
        resetBlock();
        setBlockData({
            name: '',
            type: '',
            description: '',
            fields: [
                { name: 'title', label: 'Section Title', type: 'text', default: 'Banner Title' }
            ],
            template_html: '<div className="p-6 bg-rose-50 text-neutral-800 rounded-xl my-4 text-center">\n  <h4 className="font-bold text-lg">{{title}}</h4>\n</div>'
        });
        setIsBlockOpen(true);
    };

    const handleEditBlock = (block: CustomBlock) => {
        setEditingBlock(block);
        setBlockData({
            name: block.name,
            type: block.type,
            description: block.description || '',
            fields: block.fields || [],
            template_html: block.template_html || '',
        });
        setIsBlockOpen(true);
    };

    const handleBlockFieldChange = (index: number, key: keyof CustomBlockField, value: string) => {
        const newFields = [...blockData.fields];
        newFields[index] = { ...newFields[index], [key]: value };
        setBlockData('fields', newFields);
    };

    const handleAddBlockField = () => {
        setBlockData('fields', [
            ...blockData.fields,
            { name: '', label: '', type: 'text', default: '' }
        ]);
    };

    const handleRemoveBlockField = (index: number) => {
        setBlockData('fields', blockData.fields.filter((_, i) => i !== index));
    };

    const handleBlockSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (editingBlock) {
            putBlock(`/super-admin/custom-blocks/${editingBlock.id}`, {
                onSuccess: () => {
                    setIsBlockOpen(false);
                    resetBlock();
                }
            });
        } else {
            postBlock('/super-admin/custom-blocks', {
                onSuccess: () => {
                    setIsBlockOpen(false);
                    resetBlock();
                }
            });
        }
    };

    return (
        <AppLayout breadcrumbs={breadcrumbs}>
            <Head title="System Settings" />
            <div className="flex h-full flex-1 flex-col gap-6 p-6 max-w-6xl w-full mx-auto">

                {/* Header */}
                <div className="flex flex-col gap-2">
                    <h1 className="text-3xl font-bold tracking-tight text-neutral-900 dark:text-neutral-100">
                        System Configuration Settings
                    </h1>
                    <p className="text-neutral-500 dark:text-neutral-400">
                        Configure payment gateways, templates categories, and dynamically designed layout builder blocks.
                    </p>
                </div>

                {/* Tab Navigation */}
                <div className="flex border-b border-neutral-200 dark:border-neutral-800 gap-6 mt-2 shrink-0">
                    <button
                        onClick={() => setActiveTab('config')}
                        className={`pb-3 font-bold text-sm border-b-2 transition-all flex items-center gap-2 cursor-pointer ${
                            activeTab === 'config'
                                ? 'border-blue-600 text-blue-600 dark:border-blue-500 dark:text-blue-500'
                                : 'border-transparent text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300'
                        }`}
                    >
                        <Settings className="size-4" /> General Config
                    </button>
                    <button
                        onClick={() => setActiveTab('categories')}
                        className={`pb-3 font-bold text-sm border-b-2 transition-all flex items-center gap-2 cursor-pointer ${
                            activeTab === 'categories'
                                ? 'border-blue-600 text-blue-600 dark:border-blue-500 dark:text-blue-500'
                                : 'border-transparent text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300'
                        }`}
                    >
                        <Layers className="size-4" /> Manage Categories
                    </button>
                    <button
                        onClick={() => setActiveTab('blocks')}
                        className={`pb-3 font-bold text-sm border-b-2 transition-all flex items-center gap-2 cursor-pointer ${
                            activeTab === 'blocks'
                                ? 'border-blue-600 text-blue-600 dark:border-blue-500 dark:text-blue-500'
                                : 'border-transparent text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300'
                        }`}
                    >
                        <Code className="size-4" /> Manage Custom Blocks
                    </button>
                </div>

                {/* TAB CONTENT: General Configurations */}
                {activeTab === 'config' && (
                    <form onSubmit={handleSaveConfig} className="flex flex-col gap-6 max-w-4xl">
                        {/* Razorpay Setup */}
                        <div className="rounded-2xl border border-neutral-200 bg-white p-6 shadow-xs dark:border-neutral-800 dark:bg-neutral-900 flex flex-col gap-6">
                            <div className="flex items-center gap-2.5 pb-4 border-b border-neutral-150 dark:border-neutral-800">
                                <div className="bg-blue-50 p-2.5 text-blue-600 rounded-xl dark:bg-blue-950/40 dark:text-blue-400">
                                    <Key className="size-5" />
                                </div>
                                <div className="flex flex-col">
                                    <h3 className="font-bold text-base text-neutral-900 dark:text-neutral-100">Razorpay API Credentials</h3>
                                    <p className="text-xs text-neutral-400">Used for customer checkouts and reseller online recharges</p>
                                </div>
                            </div>

                            <div className="flex flex-col gap-5">
                                <div className="flex flex-col gap-2">
                                    <div className="flex items-center justify-between">
                                        <Label htmlFor="razorpay_key_id">Razorpay Key ID</Label>
                                        {settings.razorpay_key_id && (
                                            <button
                                                type="button"
                                                onClick={() => handleDeleteKey('razorpay_key_id')}
                                                className="text-[10px] text-red-500 hover:underline flex items-center gap-1 font-semibold cursor-pointer"
                                            >
                                                <Trash2 className="size-3" /> Delete Key
                                            </button>
                                        )}
                                    </div>
                                    <Input
                                        id="razorpay_key_id"
                                        value={configData.razorpay_key_id}
                                        onChange={(e) => setConfigData('razorpay_key_id', e.target.value)}
                                        placeholder="E.g., rzp_test_R7xzyaqsmw9C9O"
                                        className="font-mono bg-neutral-50/50"
                                    />
                                </div>

                                <div className="flex flex-col gap-2">
                                    <div className="flex items-center justify-between">
                                        <div className="flex items-center gap-1.5">
                                            <Label htmlFor="razorpay_key_secret">Razorpay Key Secret</Label>
                                            {settings.has_razorpay_key_secret ? (
                                                <span className="inline-flex items-center gap-0.5 text-[10px] bg-emerald-50 text-emerald-700 px-1.5 py-0.5 rounded-full font-bold dark:bg-emerald-950/35 dark:text-emerald-400">
                                                    <CheckCircle2 className="size-3" /> Configured
                                                </span>
                                            ) : (
                                                <span className="inline-flex items-center gap-0.5 text-[10px] bg-amber-50 text-amber-700 px-1.5 py-0.5 rounded-full font-bold dark:bg-amber-950/35 dark:text-amber-400">
                                                    <ShieldAlert className="size-3" /> Not Configured
                                                </span>
                                            )}
                                        </div>

                                        {settings.has_razorpay_key_secret && (
                                            <button
                                                type="button"
                                                onClick={() => handleDeleteKey('razorpay_key_secret')}
                                                className="text-[10px] text-red-500 hover:underline flex items-center gap-1 font-semibold cursor-pointer"
                                            >
                                                <Trash2 className="size-3" /> Delete Secret
                                            </button>
                                        )}
                                    </div>
                                    <div className="relative">
                                        <Input
                                            id="razorpay_key_secret"
                                            type={showSecret ? 'text' : 'password'}
                                            value={configData.razorpay_key_secret}
                                            onChange={(e) => setConfigData('razorpay_key_secret', e.target.value)}
                                            placeholder={settings.has_razorpay_key_secret ? "â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢â€¢" : "Paste your Razorpay Key Secret here"}
                                            className="font-mono bg-neutral-50/50 pr-10"
                                        />
                                        <button
                                            type="button"
                                            onClick={() => setShowSecret(!showSecret)}
                                            className="absolute right-3 top-2.5 text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-200 cursor-pointer"
                                        >
                                            {showSecret ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Manual Bank Details & Bonus settings */}
                        <div className="rounded-2xl border border-neutral-200 bg-white p-6 shadow-xs dark:border-neutral-800 dark:bg-neutral-900 flex flex-col gap-6">
                            <div className="flex items-center gap-2.5 pb-4 border-b border-neutral-150 dark:border-neutral-800">
                                <div className="bg-emerald-50 p-2.5 text-emerald-600 rounded-xl dark:bg-emerald-950/40 dark:text-emerald-400">
                                    <Wallet className="size-5" />
                                </div>
                                <div className="flex flex-col">
                                    <h3 className="font-bold text-base text-neutral-900 dark:text-neutral-100">Reseller Wallet & Bank Details</h3>
                                    <p className="text-xs text-neutral-400">Manual payment details and wallet bonus configuration</p>
                                </div>
                            </div>

                            <div className="grid md:grid-cols-2 gap-5">
                                <div className="flex flex-col gap-2">
                                    <Label htmlFor="reseller_bank_name">Bank Name</Label>
                                    <Input
                                        id="reseller_bank_name"
                                        value={configData.reseller_bank_name}
                                        onChange={(e) => setConfigData('reseller_bank_name', e.target.value)}
                                        placeholder="e.g. HDFC Bank"
                                    />
                                </div>

                                <div className="flex flex-col gap-2">
                                    <Label htmlFor="reseller_account_holder">Account Holder Name</Label>
                                    <Input
                                        id="reseller_account_holder"
                                        value={configData.reseller_account_holder}
                                        onChange={(e) => setConfigData('reseller_account_holder', e.target.value)}
                                        placeholder="e.g. Invitify Digital Labs"
                                    />
                                </div>

                                <div className="flex flex-col gap-2">
                                    <Label htmlFor="reseller_account_number">Account Number</Label>
                                    <Input
                                        id="reseller_account_number"
                                        value={configData.reseller_account_number}
                                        onChange={(e) => setConfigData('reseller_account_number', e.target.value)}
                                        placeholder="e.g. 50100239402930"
                                    />
                                </div>

                                <div className="flex flex-col gap-2">
                                    <Label htmlFor="reseller_ifsc_code">IFSC Code</Label>
                                    <Input
                                        id="reseller_ifsc_code"
                                        value={configData.reseller_ifsc_code}
                                        onChange={(e) => setConfigData('reseller_ifsc_code', e.target.value)}
                                        placeholder="e.g. HDFC0001203"
                                    />
                                </div>

                                <div className="flex flex-col gap-2">
                                    <Label htmlFor="reseller_upi_id">UPI ID (Optional)</Label>
                                    <Input
                                        id="reseller_upi_id"
                                        value={configData.reseller_upi_id}
                                        onChange={(e) => setConfigData('reseller_upi_id', e.target.value)}
                                        placeholder="e.g. business@upi"
                                    />
                                </div>

                                <div className="flex flex-col gap-2">
                                    <Label htmlFor="reseller_default_bonus_percentage">Default Recharge Bonus (%)</Label>
                                    <Input
                                        id="reseller_default_bonus_percentage"
                                        type="number"
                                        min="0"
                                        max="100"
                                        value={configData.reseller_default_bonus_percentage}
                                        onChange={(e) => setConfigData('reseller_default_bonus_percentage', e.target.value)}
                                    />
                                </div>
                            </div>
                        </div>

                        {configSuccess && (
                            <div className="p-3 bg-emerald-50 border border-emerald-100 rounded-lg text-emerald-800 text-xs font-semibold dark:bg-emerald-950/30 dark:border-emerald-900/50 dark:text-emerald-400 animate-fade-in">
                                âœ“ System configuration settings updated successfully.
                            </div>
                        )}

                        <div className="flex justify-end pt-2">
                            <Button type="submit" disabled={configProcessing} className="bg-blue-650 hover:bg-blue-700 text-white font-semibold shadow-md">
                                <Save className="size-4 mr-2" /> Save configuration
                            </Button>
                        </div>
                    </form>
                )}

                {/* TAB CONTENT: Categories Management */}
                {activeTab === 'categories' && (
                    <div className="flex flex-col gap-6">
                        <div className="flex items-center justify-between">
                            <div>
                                <h3 className="text-xl font-bold">Categories Directory</h3>
                                <p className="text-xs text-neutral-400 mt-1">Manage categories dynamically used for invitation and card filtering.</p>
                            </div>
                            <Button onClick={handleAddCategory} className="bg-blue-600 hover:bg-blue-700 text-white font-semibold">
                                <Plus className="size-4 mr-1.5" /> Add Category
                            </Button>
                        </div>

                        <div className="border rounded-2xl bg-white dark:bg-neutral-900 overflow-hidden shadow-xs">
                            <table className="w-full text-left text-sm border-collapse">
                                <thead>
                                    <tr className="bg-neutral-50 dark:bg-neutral-950 text-neutral-500 font-extrabold border-b">
                                        <th className="p-4">Name</th>
                                        <th className="p-4">Slug</th>
                                        <th className="p-4 text-right">Actions</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {categories.map(cat => (
                                        <tr key={cat.id} className="border-b last:border-0 hover:bg-neutral-50/50">
                                            <td className="p-4 font-bold">{cat.name}</td>
                                            <td className="p-4 font-mono text-xs">{cat.slug}</td>
                                            <td className="p-4 text-right flex justify-end gap-2">
                                                <Button onClick={() => handleEditCategory(cat)} variant="outline" size="sm">
                                                    <Pencil className="size-3.5 mr-1" /> Edit
                                                </Button>
                                                <Button 
                                                    onClick={() => { if (confirm('Are you sure you want to delete this category?')) router.delete(`/super-admin/categories/${cat.id}`) }}
                                                    variant="destructive" 
                                                    size="sm"
                                                >
                                                    <Trash className="size-3.5" />
                                                </Button>
                                            </td>
                                        </tr>
                                    ))}
                                    {categories.length === 0 && (
                                        <tr>
                                            <td colSpan={3} className="p-8 text-center text-neutral-400">No categories found. Click Add Category to create one.</td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>

                        {/* Category Modal */}
                        <Dialog open={isCategoryOpen} onOpenChange={setIsCategoryOpen}>
                            <DialogContent>
                                <DialogHeader>
                                    <DialogTitle>{editingCategory ? 'Edit Category' : 'Create Dynamic Category'}</DialogTitle>
                                </DialogHeader>
                                <form onSubmit={handleCategorySubmit} className="flex flex-col gap-4 py-4">
                                    <div className="grid gap-2">
                                        <Label htmlFor="category_name">Category Name</Label>
                                        <Input
                                            id="category_name"
                                            value={categoryData.name}
                                            onChange={e => setCategoryData('name', e.target.value)}
                                            placeholder="e.g. Wedding Reception"
                                            required
                                        />
                                        {categoryErrors.name && <p className="text-red-500 text-xs">{categoryErrors.name}</p>}
                                    </div>
                                    <div className="grid gap-2">
                                        <Label htmlFor="category_slug">Slug / Identifier</Label>
                                        <Input
                                            id="category_slug"
                                            value={categoryData.slug}
                                            onChange={e => setCategoryData('slug', e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, ''))}
                                            placeholder="e.g. wedding-reception"
                                        />
                                        <span className="text-[10px] text-neutral-400">Leave blank to generate slug automatically from the name.</span>
                                        {categoryErrors.slug && <p className="text-red-500 text-xs">{categoryErrors.slug}</p>}
                                    </div>
                                    <DialogFooter className="mt-4">
                                        <Button type="button" variant="outline" onClick={() => setIsCategoryOpen(false)}>Cancel</Button>
                                        <Button type="submit" disabled={categoryProcessing} className="bg-blue-650 hover:bg-blue-700 text-white font-semibold">
                                            {editingCategory ? 'Update Category' : 'Create Category'}
                                        </Button>
                                    </DialogFooter>
                                </form>
                            </DialogContent>
                        </Dialog>
                    </div>
                )}

                {/* TAB CONTENT: Custom Layout Blocks Management */}
                {activeTab === 'blocks' && (
                    <div className="flex flex-col gap-6">
                        <div className="flex items-center justify-between">
                            <div>
                                <h3 className="text-xl font-bold">Custom Blocks Directory</h3>
                                <p className="text-xs text-neutral-400 mt-1">Design layout blocks dynamically to extend the block-based builder dropdown.</p>
                            </div>
                            <Button onClick={handleAddBlock} className="bg-blue-600 hover:bg-blue-700 text-white font-semibold">
                                <Plus className="size-4 mr-1.5" /> Design Custom Block
                            </Button>
                        </div>

                        <div className="grid gap-6 md:grid-cols-2">
                            {customBlocks.map(block => (
                                <div key={block.id} className="border rounded-2xl p-5 bg-white dark:bg-neutral-900 shadow-xs flex flex-col justify-between hover:shadow-md transition-all">
                                    <div>
                                        <div className="flex items-center justify-between mb-2">
                                            <h4 className="font-extrabold text-base">{block.name}</h4>
                                            <span className="bg-blue-50 text-blue-700 font-mono text-[10px] px-2 py-0.5 rounded-md dark:bg-blue-950/40 dark:text-blue-400">{block.type}</span>
                                        </div>
                                        <p className="text-xs text-neutral-400 leading-relaxed mb-4">{block.description || 'No description provided.'}</p>
                                        <div className="border-t pt-3 mt-3">
                                            <Label className="text-[10px] uppercase font-black text-neutral-400">Supported Parameters</Label>
                                            <div className="flex flex-wrap gap-1.5 mt-1">
                                                {block.fields.map(f => (
                                                    <span key={f.name} className="text-[9px] bg-neutral-100 text-neutral-600 px-1.5 py-0.5 rounded font-semibold dark:bg-neutral-800 dark:text-neutral-350">
                                                        {f.label} ({f.type})
                                                    </span>
                                                ))}
                                            </div>
                                        </div>
                                    </div>
                                    <div className="flex gap-2 border-t pt-4 mt-6">
                                        <Button onClick={() => handleEditBlock(block)} variant="outline" size="sm" className="flex-1">
                                            <Pencil className="size-3.5 mr-1" /> Edit Layout Block
                                        </Button>
                                        <Button 
                                            onClick={() => { if (confirm('Are you sure you want to delete this custom block?')) router.delete(`/super-admin/custom-blocks/${block.id}`) }}
                                            variant="destructive" 
                                            size="sm"
                                        >
                                            <Trash className="size-3.5" />
                                        </Button>
                                    </div>
                                </div>
                            ))}
                            {customBlocks.length === 0 && (
                                <div className="col-span-2 rounded-2xl border-2 border-dashed p-12 text-center bg-white/50 dark:bg-neutral-900/30 flex flex-col items-center justify-center">
                                    <Code className="size-10 text-neutral-300 mb-2" />
                                    <h4 className="font-bold text-neutral-600">No Custom Blocks Seeded</h4>
                                    <p className="text-xs text-neutral-400 max-w-sm mt-1 mb-4">Design dynamic layout blocks with custom Tailwind/HTML templates and load them dynamically in the invitation website builder.</p>
                                    <Button onClick={handleAddBlock} className="bg-blue-600 hover:bg-blue-700 text-white font-semibold">Create First Block</Button>
                                </div>
                            )}
                        </div>

                        {/* Custom Block Modal Designer */}
                        <Dialog open={isBlockOpen} onOpenChange={setIsBlockOpen}>
                            <DialogContent className="max-w-[75vw] w-[75vw] h-[85vh] flex flex-col p-0">
                                <DialogHeader className="p-6 border-b">
                                    <DialogTitle>{editingBlock ? `Edit: ${editingBlock.name}` : 'Design Dynamic Layout Block'}</DialogTitle>
                                </DialogHeader>

                                <div className="flex-1 overflow-y-auto p-6 grid md:grid-cols-2 gap-8">
                                    {/* Left inputs */}
                                    <div className="flex flex-col gap-5">
                                        <div className="grid gap-2">
                                            <Label htmlFor="block_name">Block Name</Label>
                                            <Input
                                                id="block_name"
                                                value={blockData.name}
                                                onChange={e => setBlockData('name', e.target.value)}
                                                placeholder="e.g. Colored Banner Alert"
                                                required
                                            />
                                            {blockErrors.name && <p className="text-red-500 text-xs">{blockErrors.name}</p>}
                                        </div>

                                        <div className="grid gap-2">
                                            <Label htmlFor="block_type">Unique Type Identifier</Label>
                                            <Input
                                                id="block_type"
                                                value={blockData.type}
                                                onChange={e => setBlockData('type', e.target.value.toLowerCase().replace(/[^a-z0-9_]/g, ''))}
                                                placeholder="e.g. custom_colored_banner"
                                                required
                                                disabled={!!editingBlock}
                                            />
                                            {blockErrors.type && <p className="text-red-500 text-xs">{blockErrors.type}</p>}
                                        </div>

                                        <div className="grid gap-2">
                                            <Label htmlFor="block_description">Short Description</Label>
                                            <textarea
                                                id="block_description"
                                                value={blockData.description}
                                                onChange={e => setBlockData('description', e.target.value)}
                                                placeholder="Briefly explain what this layout block is intended for."
                                                rows={2}
                                                className="flex w-full rounded-md border border-neutral-200 bg-transparent px-3 py-2 text-sm shadow-xs focus-visible:outline-hidden focus-visible:ring-1 focus-visible:ring-neutral-950 dark:bg-neutral-950"
                                            />
                                        </div>

                                        <div className="border-t pt-4 mt-2">
                                            <div className="flex items-center justify-between mb-4">
                                                <Label className="font-extrabold text-sm">Configurable Field Parameters</Label>
                                                <Button type="button" onClick={handleAddBlockField} variant="outline" size="sm" className="h-7 text-xs">
                                                    + Add Parameter
                                                </Button>
                                            </div>
                                            <div className="flex flex-col gap-3">
                                                {blockData.fields.map((field, idx) => (
                                                    <div key={idx} className="flex gap-2 items-center p-3 border rounded-xl bg-neutral-50/50 relative">
                                                        <div className="flex-1 grid grid-cols-2 gap-2">
                                                            <div className="flex flex-col gap-1">
                                                                <span className="text-[10px] text-neutral-400 font-bold uppercase">Name / Key</span>
                                                                <Input 
                                                                    value={field.name}
                                                                    onChange={e => handleBlockFieldChange(idx, 'name', e.target.value.toLowerCase().replace(/[^a-z0-9_]/g, ''))}
                                                                    placeholder="title" 
                                                                    className="h-8 text-xs font-mono"
                                                                    required
                                                                />
                                                            </div>
                                                            <div className="flex flex-col gap-1">
                                                                <span className="text-[10px] text-neutral-400 font-bold uppercase">Field Label</span>
                                                                <Input 
                                                                    value={field.label}
                                                                    onChange={e => handleBlockFieldChange(idx, 'label', e.target.value)}
                                                                    placeholder="Banner Title" 
                                                                    className="h-8 text-xs"
                                                                    required
                                                                />
                                                            </div>
                                                            <div className="flex flex-col gap-1">
                                                                <span className="text-[10px] text-neutral-400 font-bold uppercase">Type</span>
                                                                <select 
                                                                    value={field.type} 
                                                                    onChange={e => handleBlockFieldChange(idx, 'type', e.target.value as any)}
                                                                    className="h-8 rounded-md border border-neutral-200 bg-white text-xs px-2 shadow-xs dark:bg-neutral-900"
                                                                >
                                                                    <option value="text">Text Input</option>
                                                                    <option value="textarea">Textarea Block</option>
                                                                    <option value="number">Numeric Range</option>
                                                                    <option value="color">Hex Color Picker</option>
                                                                </select>
                                                            </div>
                                                            <div className="flex flex-col gap-1">
                                                                <span className="text-[10px] text-neutral-400 font-bold uppercase">Default Value</span>
                                                                <Input 
                                                                    value={field.default}
                                                                    onChange={e => handleBlockFieldChange(idx, 'default', e.target.value)}
                                                                    placeholder="#ffffff" 
                                                                    className="h-8 text-xs"
                                                                />
                                                            </div>
                                                        </div>
                                                        <button 
                                                            type="button" 
                                                            onClick={() => handleRemoveBlockField(idx)}
                                                            className="text-red-500 hover:text-red-700 p-1.5 rounded-lg hover:bg-red-50 cursor-pointer"
                                                        >
                                                            <Trash className="size-4" />
                                                        </button>
                                                    </div>
                                                ))}
                                                {blockData.fields.length === 0 && (
                                                    <p className="text-xs text-neutral-400 text-center italic py-2">Add at least one input parameter.</p>
                                                )}
                                            </div>
                                        </div>
                                    </div>

                                    {/* Right template */}
                                    <div className="flex flex-col gap-4">
                                        <div className="grid gap-2 flex-1 flex flex-col">
                                            <Label htmlFor="block_template" className="font-extrabold flex items-center justify-between">
                                                <span>HTML / Tailwind CSS Template Markup</span>
                                                <span className="text-[10px] bg-blue-50 text-blue-700 px-2 py-0.5 rounded font-mono font-black normal-case">HTML</span>
                                            </Label>
                                            <textarea
                                                id="block_template"
                                                value={blockData.template_html}
                                                onChange={e => setBlockData('template_html', e.target.value)}
                                                placeholder="Write your HTML here..."
                                                className="flex-1 w-full rounded-md border border-neutral-200 bg-transparent px-3 py-2 text-xs font-mono shadow-xs focus-visible:outline-hidden focus-visible:ring-1 focus-visible:ring-neutral-950 dark:bg-neutral-950 min-h-[300px]"
                                                required
                                            />
                                        </div>
                                        <div className="p-4 bg-blue-50/50 border border-blue-100 rounded-2xl text-xs text-blue-800 dark:bg-blue-950/20 dark:border-blue-950 dark:text-blue-300">
                                            <h5 className="font-bold mb-1">Templating Guidelines:</h5>
                                            <ul className="list-disc pl-4 space-y-1">
                                                <li>Wrap parameter keys in double curly braces (e.g. <code className="font-bold bg-white/60 dark:bg-black/20 px-1 rounded">{"{{title}}"}</code> or <code className="font-bold bg-white/60 dark:bg-black/20 px-1 rounded">{"{{bg_color}}"}</code>).</li>
                                                <li>Double curly braces will be dynamically replaced by configured client values in the website builder.</li>
                                                <li>Use regular Tailwind CSS utility classes directly inside your markup elements for visual styling.</li>
                                            </ul>
                                        </div>
                                    </div>
                                </div>

                                <DialogFooter className="p-4 border-t shrink-0">
                                    <Button type="button" variant="outline" onClick={() => setIsBlockOpen(false)}>Cancel</Button>
                                    <Button type="button" onClick={handleBlockSubmit} disabled={blockProcessing} className="bg-blue-650 hover:bg-blue-700 text-white font-semibold">
                                        <Save className="size-4 mr-2" /> {editingBlock ? 'Save Changes' : 'Create Block'}
                                    </Button>
                                </DialogFooter>
                            </DialogContent>
                        </Dialog>
                    </div>
                )}
            </div>
        </AppLayout>
    );
}
